cd /app/tmp && cat > asan/harness.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int solve(const unsigned long long *addr, const int *lens, int n,
          const unsigned long long *caps, int S, int stride, int *out_cuts);
static unsigned long long rngstate = 0x123456789abcdefULL;
static unsigned long long rnd(void) {
    rngstate ^= rngstate << 13; rngstate ^= rngstate >> 7; rngstate ^= rngstate << 17;
    return rngstate;
}
int main(void) {
    enum { MAXN = 2048 };
    static unsigned long long addr[2 * MAXN];
    static int lens[MAXN];
    static unsigned long long caps[16];
    static int cuts[17];
    int trial;
    for (trial = 0; trial < 3000; trial++) {
        int n = (int)(rnd() % 90);
        int i;
        for (i = 0; i < n; i++) {
            int L = (int)(rnd() % 129);
            unsigned long long hi = rnd(), lo = rnd();
            if (L <= 64) hi &= (L == 64) ? ~0ULL : (~0ULL << (64 - L));
            if (L >= 64) lo = (L == 64) ? 0 : (lo & (~0ULL << (128 - L)));
            else lo = 0;
            if (L == 0) { hi = 0; lo = 0; }
            addr[2 * i] = hi; addr[2 * i + 1] = lo; lens[i] = L;
        }
        int S = 4 + (int)(rnd() % 13);
        int stride = 1 + (int)(rnd() % 32);
        if (S * stride < 128) stride = 128 / S + (128 % S ? 1 : 0);
        if (stride > 32) stride = 32;
        for (i = 0; i < S; i++) caps[i] = 100 + rnd() % 100000;
        int rc = solve(addr, lens, n, caps, S, stride, cuts);
        if (rc != 0 && rc != 1) { printf("bad rc %d\n", rc); return 1; }
        if (rc == 1) {
            if (cuts[0] != 0 || cuts[S] != 128) { printf("bad endpoints\n"); return 1; }
            for (i = 0; i < S; i++)
                if (cuts[i + 1] - cuts[i] < 1 || cuts[i + 1] - cuts[i] > stride) {
                    printf("bad gap\n"); return 1;
                }
        }
    }
    /* extremes */
    int rc;
    rc = solve(addr, lens, 0, caps, 4, 32, cuts); printf("empty: %d\n", rc);
    lens[0] = 0; addr[0] = 0; addr[1] = 0;
    rc = solve(addr, lens, 1, caps, 16, 8, cuts); printf("only /0: %d\n", rc);
    for (int i = 0; i < 2048; i++) {
        lens[i] = 128;
        addr[2 * i] = ((unsigned long long)i << 53) | (rnd() >> 11);
        addr[2 * i + 1] = rnd();
    }
    for (int i = 0; i < 16; i++) caps[i] = 1000000000ULL;
    rc = solve(addr, lens, 2048, caps, 16, 32, cuts); printf("2048 deep: %d\n", rc);
    for (int i = 0; i <= 128; i++) { lens[i] = i; addr[2 * i] = 0; addr[2 * i + 1] = 0; }
    rc = solve(addr, lens, 129, caps, 16, 32, cuts); printf("full chain: %d\n", rc);
    rc = solve(addr, lens, 129, caps, 4, 32, cuts); printf("full chain S=4: %d\n", rc);
    for (int i = 0; i < 4; i++) caps[i] = 1;
    rc = solve(addr, lens, 129, caps, 4, 32, cuts); printf("chain infeasible: %d\n", rc);
    printf("HARNESS OK\n");
    return 0;
}
EOF
gcc -O1 -g -fsanitize=address,undefined -o /app/tmp/asan/harness /app/tmp/asan/harness.c /app/submit/core.c && time /app/tmp/asan/harness
